// Service worker — offline cache for the whole suite (plan §5.5 SW-01…04, §10.2 F-1/F-3; WP09).
//   - Precaches every same-origin asset the field needs: the list is generated by scripts/gen-precache.mjs into
//     sw-precache.js (VTOL_PRECACHE.assets + a content hash), so any deployed change gives a new worker.
//   - Cache name = 'vtol-manual-' + VTOL_VERSION.app + '-' + content hash; older vtol-manual-* caches are deleted
//     when the new worker activates.
//   - Pages (HTML) and page code (.js / .css): network-first with a timeout, cache when offline. Code is kept in step
//     with the HTML that loads it (a stale tools-core.js next to a newer index.html would break the page).
//   - Every other same-origin asset (images, diagrams, fonts, icons, manifest, Leaflet images): stale-while-revalidate.
//   - Never cached: anything cross-origin — the GCS app API http://127.0.0.1:47800, Open-Meteo (the Tools page keeps
//     its own weather cache), Nominatim, map tiles and terrain (the map keeps its own IndexedDB tile store).
//   - A new worker waits until the page asks it to take over (toast "New version available — RELOAD", js/field.js).
importScripts('./js/version.js', './sw-precache.js');

const CACHE_PREFIX = 'vtol-manual-';
const CACHE = CACHE_PREFIX + self.VTOL_VERSION.app + '-' + self.VTOL_PRECACHE.hash;
const ASSETS = self.VTOL_PRECACHE.assets;
const NETWORK_TIMEOUT_MS = 4000;   // weak field signal: fall back to the cached copy after this
const NEVER_CACHE = [/^http:\/\/127\.0\.0\.1:47800\//, /^https:\/\/[^/]*open-meteo\.com\//, /^https:\/\/nominatim\.openstreetmap\.org\//];

self.addEventListener('install', e => {
  // cache:'reload' bypasses the HTTP cache, so the new version is precached from the server.
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS.map(u => new Request(u, { cache: 'reload' })))));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k.startsWith(CACHE_PREFIX) && k !== CACHE).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('message', e => {
  if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting();
});

function isPage(url, req) {
  return req.mode === 'navigate' || url.pathname.endsWith('.html') || url.pathname.endsWith('/');
}
function isCode(url) {
  return url.pathname.endsWith('.js') || url.pathname.endsWith('.css');
}

// Cached copy of a request: exact match first, then without the query string (index.html?x → index.html).
function fromCache(req) {
  return caches.open(CACHE).then(c => c.match(req).then(r => r || c.match(req, { ignoreSearch: true })));
}
function store(req, res) {
  if (res && res.status === 200 && res.type === 'basic') {
    const copy = res.clone();
    caches.open(CACHE).then(c => c.put(req, copy)).catch(() => {});
  }
  return res;
}
function offlineResponse(page) {
  return new Response(page ? '<!DOCTYPE html><meta charset="utf-8"><title>Offline</title><body style="background:#000;color:#fff;font:16px monospace;padding:16px">OFFLINE — this page is not in the offline cache. Open <a style="color:#f97316" href="./index.html">FLIGHT TOOLS</a>.</body>' : '',
    { status: 503, statusText: 'Offline', headers: { 'Content-Type': page ? 'text/html; charset=utf-8' : 'text/plain' } });
}

// Network-first: the network answer when it arrives within the timeout, else the cached copy (a late network answer
// still updates the cache). A server error prefers the cached copy. Offline with no cached copy → 503.
function networkFirst(req, page) {
  return new Promise(resolve => {
    let done = false;
    const finish = r => { if (!done) { done = true; resolve(r); } };
    const net = fetch(req).then(res => store(req, res));
    const fallback = () => fromCache(req).then(c => c || net.catch(() => offlineResponse(page)));
    const timer = setTimeout(() => fallback().then(finish), NETWORK_TIMEOUT_MS);
    net.then(res => {
      clearTimeout(timer);
      if (res.ok || res.status === 304) finish(res);
      else fromCache(req).then(c => finish(c || res));
    }, () => { clearTimeout(timer); fallback().then(finish); });
  });
}

// Stale-while-revalidate: the cached copy at once, refreshed in the background; network only when not cached.
function staleWhileRevalidate(e, req) {
  return fromCache(req).then(cached => {
    const net = fetch(req).then(res => store(req, res));
    if (cached) { e.waitUntil(net.catch(() => {})); return cached; }
    return net.catch(() => offlineResponse(false));
  });
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;          // cross-origin: never intercepted, never cached
  if (NEVER_CACHE.some(re => re.test(req.url))) return;
  if (url.pathname.endsWith('/sw.js') || url.pathname.endsWith('/sw-precache.js')) return;
  if (isPage(url, req)) e.respondWith(networkFirst(req, true));
  else if (isCode(url)) e.respondWith(networkFirst(req, false));
  else e.respondWith(staleWhileRevalidate(e, req));
});
